#include "my_stm32f4.h"
#include "ir_sensor.h"
#include "hcsr04.h"
#include "servo.h"
#include "parking_config.h"
#include "led.h"
#include "freertos_init.h"
#include <stdio.h>

/* Global variable to be accessed by tasks.c */
uint32_t parking_capacity;

int main(void) {
    // 1. Initialize all hardware
    IR_Sensor_Init();
    HCSR04_Init();
    Servo_Init();
    LED_Init();

    Servo_SetAngle(0);
    
    printf("Loading config\r\n");
    
    //Handles error if the flash memory is not initialized or corrupted
    if (!ParkingConfig_Init(&parking_capacity)) {
        printf("Flash config ERROR\r\n");
        while (1) {
            Servo_SetAngle(0);
        }
    }
    
    /* Initialize the RTOS kernel and start the scheduler. */
    FreeRTOS_Init();
    while (1) {
    }
}
